use super::ascii;

pub struct Inflector;

impl Inflector {
    pub fn initialize() {}

    pub fn pluralize(word: &str) -> String {
        if word.is_empty() {
            String::new()
        } else {
            let mut out = String::with_capacity(word.len() + 1);
            out.push_str(word);
            out.push('s');
            out
        }
    }

    pub fn singularize(word: &str) -> String {
        if let Some(stem) = word.strip_suffix('s') {
            stem.to_string()
        } else {
            word.to_string()
        }
    }

    pub fn camelize(word: &str) -> String {
        let mut parts = word.split('_').filter(|part| !part.is_empty());
        let Some(first) = parts.next() else {
            return String::new();
        };

        let mut out = String::with_capacity(word.len());
        out.push_str(first);
        for part in parts {
            out.push_str(&ascii::uppercase_first(part));
        }
        out
    }

    pub fn underscore(word: &str) -> String {
        let mut out = String::with_capacity(word.len());

        for (index, ch) in word.chars().enumerate() {
            if ch.is_ascii_uppercase() {
                if index != 0 {
                    out.push('_');
                }
                out.push(ch.to_ascii_lowercase());
            } else {
                out.push(ch);
            }
        }

        out
    }

    pub fn classify(word: &str) -> String {
        let mut out = String::with_capacity(word.len());

        for part in word.split('_').filter(|part| !part.is_empty()) {
            out.push_str(&ascii::uppercase_first(part));
        }

        out
    }

    pub fn tableize(word: &str) -> String {
        Self::pluralize(&Self::underscore(word))
    }

    pub fn humanize(word: &str) -> String {
        let replaced: String = word
            .chars()
            .map(|ch| if ch == '_' { ' ' } else { ch })
            .collect();

        ascii::uppercase_first(&replaced)
    }

    pub fn titleize(word: &str) -> String {
        ascii::titleize(word)
    }

    pub fn dasherize(word: &str) -> String {
        word.chars()
            .map(|ch| if ch == '_' { '-' } else { ch })
            .collect()
    }

    pub fn parameterize(word: &str) -> String {
        let mut out = String::with_capacity(word.len());

        for ch in word.chars() {
            if ch.is_ascii_alphanumeric() {
                out.push(ch.to_ascii_lowercase());
            } else if ch == ' ' {
                out.push('-');
            }
        }

        out
    }

    pub fn upcase(word: &str) -> String {
        ascii::upcase(word)
    }

    pub fn downcase(word: &str) -> String {
        ascii::downcase(word)
    }

    pub fn capitalize(word: &str) -> String {
        ascii::capitalize(word)
    }
}

pub fn uppercase_char(ch: char) -> char {
    if ch.is_ascii_lowercase() {
        ch.to_ascii_uppercase()
    } else {
        ch
    }
}

pub fn lowercase_char(ch: char) -> char {
    if ch.is_ascii_uppercase() {
        ch.to_ascii_lowercase()
    } else {
        ch
    }
}

pub fn uppercase_first(input: &str) -> String {
    let mut chars = input.chars();
    let Some(first) = chars.next() else {
        return String::new();
    };

    let mut out = String::with_capacity(input.len());
    out.push(uppercase_char(first));
    out.extend(chars);
    out
}

pub fn capitalize(input: &str) -> String {
    let mut chars = input.chars();
    let Some(first) = chars.next() else {
        return String::new();
    };

    let mut out = String::with_capacity(input.len());
    out.push(uppercase_char(first));
    for ch in chars {
        out.push(lowercase_char(ch));
    }
    out
}

pub fn titleize(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    let mut start_of_word = true;

    for ch in input.chars() {
        if ch == ' ' {
            out.push(ch);
            start_of_word = true;
        } else if start_of_word {
            out.push(uppercase_char(ch));
            start_of_word = false;
        } else {
            out.push(lowercase_char(ch));
        }
    }

    out
}

pub fn upcase(input: &str) -> String {
    input.chars().map(uppercase_char).collect()
}

pub fn downcase(input: &str) -> String {
    input.chars().map(lowercase_char).collect()
}

