mod inflection;

use inflection::Inflector;

fn main() {
    Inflector::initialize();

    let args: Vec<String> = std::env::args().collect();
    if args.len() > 1 {
        let word = &args[1];

        println!("{}", Inflector::pluralize(word));
        println!("{}", Inflector::singularize(&(word.to_owned() + "s")));
        println!("{}", Inflector::camelize(&("test_".to_owned() + word)));
        println!("{}", Inflector::underscore(&("Test".to_owned() + word)));
        println!("{}", Inflector::classify(&(word.to_owned() + "_table")));
        println!("{}", Inflector::tableize(&(word.to_owned() + "Class")));
        println!("{}", Inflector::humanize(&(word.to_owned() + "_id")));
        println!("{}", Inflector::titleize(word));
        println!("{}", Inflector::dasherize(word));
        println!("{}", Inflector::parameterize(&("The ".to_owned() + word + " Test")));
        println!("{}", Inflector::upcase(word));
        println!("{}", Inflector::downcase(word));
        println!("{}", Inflector::capitalize(word));
    }
}
